import {hourPeriods,rowState,selectRow,dragHours,describeHours} from './map-hours-lab-model.js';
const grid=document.getElementById('hour-grid'),status=document.getElementById('selection'),preview=document.getElementById('preview');
let selected=new Set(Array.from({length:24},(_,i)=>i)),gesture=null,commits=0;
grid.innerHTML=hourPeriods.map(([name,start])=>`<div class="hour-row"><button class="period" role="checkbox" aria-checked="true" data-start="${start}" aria-label="${name}: весь ряд ${String(start).padStart(2,'0')}–${String(start+5).padStart(2,'0')}"><span class="switch" aria-hidden="true"></span><span class="period-label">${name}<small>${String(start).padStart(2,'0')}–${String(start+5).padStart(2,'0')}</small></span></button>${Array.from({length:6},(_,i)=>{const h=start+i;return `<button class="hour" data-hour="${h}" aria-label="${String(h).padStart(2,'0')}:00–${String(h).padStart(2,'0')}:59" aria-pressed="true">${String(h).padStart(2,'0')}</button>`;}).join('')}</div>`).join('');
function draw(){const visible=gesture?.draft||selected;grid.querySelectorAll('[data-hour]').forEach(button=>{const h=+button.dataset.hour;button.setAttribute('aria-pressed',String(visible.has(h)));button.classList.toggle('is-preview',!!gesture&&visible.has(h)!==selected.has(h));});grid.querySelectorAll('[data-start]').forEach(button=>button.setAttribute('aria-checked',rowState(visible,+button.dataset.start)));status.textContent=describeHours(selected);grid.dataset.commits=String(commits);preview.hidden=!gesture;if(gesture)preview.textContent='Предварительно: '+describeHours(visible)+' · отпустите для выбора';}
function commit(next){selected=next;commits++;draw();}
function cancel(){if(!gesture)return;const id=gesture.id;gesture=null;if(grid.hasPointerCapture(id))grid.releasePointerCapture(id);draw();}
grid.addEventListener('pointerdown',event=>{const button=event.target.closest('[data-hour]');if(!button||event.button!==0||!event.isPrimary||gesture)return;event.preventDefault();button.focus({preventScroll:true});const start=+button.dataset.hour;gesture={id:event.pointerId,start,enable:!selected.has(start),draft:dragHours(selected,start,start,!selected.has(start))};grid.setPointerCapture(event.pointerId);draw();});
grid.addEventListener('pointermove',event=>{if(!gesture||event.pointerId!==gesture.id)return;const button=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-hour]');if(!button||!grid.contains(button))return;gesture.draft=dragHours(selected,gesture.start,+button.dataset.hour,gesture.enable);draw();});
grid.addEventListener('pointerup',event=>{if(!gesture||event.pointerId!==gesture.id)return;const next=gesture.draft;gesture=null;if(grid.hasPointerCapture(event.pointerId))grid.releasePointerCapture(event.pointerId);commit(next);});
grid.addEventListener('pointercancel',cancel);grid.addEventListener('lostpointercapture',cancel);
grid.querySelectorAll('[data-hour]').forEach(button=>button.addEventListener('click',event=>{if(event.detail!==0||gesture)return;const h=+button.dataset.hour;commit(dragHours(selected,h,h,!selected.has(h)));}));
grid.querySelectorAll('[data-start]').forEach(button=>button.addEventListener('click',()=>{cancel();commit(selectRow(selected,+button.dataset.start));}));
document.getElementById('all-hours').onclick=()=>{cancel();commit(new Set(Array.from({length:24},(_,i)=>i)));};document.getElementById('clear-hours').onclick=()=>{cancel();commit(new Set());};
document.addEventListener('keydown',event=>{if(event.key==='Escape')cancel();});window.addEventListener('blur',cancel);draw();
